using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.SGR.PerfilMenuBotones;using GraphApi.Services.SGR.PerfilMenuBotones;namespace GraphApi.Controllers.SGR.PerfilMenuBotones{    /// <summary>    /// Gestión de PerfilMenuBotones: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("SGR/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre PerfilMenuBotones")]    public class PerfilMenuBotonesController : Controller    {        private readonly IPerfilMenuBotonesService _objService;        public PerfilMenuBotonesController(IPerfilMenuBotonesService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los PerfilMenuBotones, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="perfilMenuBotonID">PerfilMenuBotonID</param>        /// <param name="perfilID">PerfilID</param>        /// <param name="perfil">Perfil</param>        /// <param name="menuBotonID">MenuBotonID</param>        /// <param name="boton">Boton</param>        /// <param name="accion">Accion</param>        /// <param name="menuID">MenuID</param>        /// <param name="tituloMenu">TituloMenu</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de PerfilMenuBotones</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar PerfilMenuBotones",            Description = "Devuelve PerfilMenuBotones aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadPerfilMenuBotones>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadPerfilMenuBotones>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? perfilMenuBotonID,            [FromQuery] int? perfilID,            [FromQuery] string? perfil,            [FromQuery] int? menuBotonID,            [FromQuery] string? boton,            [FromQuery] string? accion,            [FromQuery] int? menuID,            [FromQuery] string? tituloMenu,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetPerfilMenuBotonesDynamic(                perfilMenuBotonID,                 perfilID,                 perfil,                 menuBotonID,                 boton,                 accion,                 menuID,                 tituloMenu,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo PerfilMenuBotone.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del PerfilMenuBotone a crear.</param>        /// <returns>El PerfilMenuBotone recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear PerfilMenuBotones",            Description = "Inserta un nuevo PerfilMenuBotone en la base de datos."        )]        [ProducesResponseType(typeof(clReadPerfilMenuBotones), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadPerfilMenuBotones>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreatePerfilMenuBotones objInput)        {            var vCreated = await _objService.CreatePerfilMenuBotones(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de PerfilMenuBotone.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del PerfilMenuBotone.</param>        /// <returns>El PerfilMenuBotone actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar PerfilMenuBotones",            Description = "Actualiza uno o varios campos de PerfilMenuBotone existente."        )]        [ProducesResponseType(typeof(clReadPerfilMenuBotones), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadPerfilMenuBotones>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdatePerfilMenuBotones objInput)        {            var vUpdated = await _objService.UpdatePerfilMenuBotones(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un PerfilMenuBotone por su ID.        /// </summary>        [HttpDelete("{nPerfilMenuBotonesID:int}")]        [SwaggerOperation(            Summary = "Eliminar PerfilMenuBotone",            Description = "Borra un PerfilMenuBotone si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nPerfilMenuBotonesID)        {            var success = await _objService.DeletePerfilMenuBotones(nPerfilMenuBotonesID);            return success ? NoContent() : NotFound();        }    }}